import '../../../../core/constants/firestore_paths.dart'; import '../../../../core/services/firebase_firestore_service.dart'; import '../models/exam_model.dart'; abstract class ExamRemoteDataSource { Future<List<ExamModel>> getExams(); Future<void> save(ExamModel exam); String generateId(); } class ExamRemoteDataSourceImpl implements ExamRemoteDataSource { ExamRemoteDataSourceImpl({required FirebaseFirestoreService firestoreService}):_service=firestoreService; final FirebaseFirestoreService _service; @override Future<List<ExamModel>> getExams()async{final data=await _service.collection(FirestorePaths.examConfigurations).orderBy('createdAt',descending:true).get();return data.docs.map((doc)=>ExamModel.fromMap({...doc.data(),'id':doc.id})).toList();} @override Future<void> save(ExamModel exam)=>_service.collection(FirestorePaths.examConfigurations).doc(exam.id).set(exam.toMap()); @override String generateId()=>_service.collection(FirestorePaths.examConfigurations).doc().id; }
